<!-- Admin 逐笔结算结果主页面：展示后端冻结的来源金额、直接汇率、方向和目标金额，禁止前端重新计算。 -->
<template>
    <div class="app-container settlement-list-page">
        <el-form v-show="showSearch" :model="query" inline size="small" class="search-form" label-width="92px">
            <el-form-item :label="t('transaction.settlement.batchNo')"><el-input v-model.trim="query.settlementBatchNo" clearable @keyup.enter="handleSearch" /></el-form-item>
            <el-form-item :label="t('transaction.fields.merchantId')"><MerchantRemoteSelect v-model="query.merchantId" @change="handleSearch" /></el-form-item>
            <el-form-item :label="t('transaction.fields.transactionId')"><el-input v-model.trim="query.sourceTransactionId" clearable @keyup.enter="handleSearch" /></el-form-item>
            <el-form-item :label="t('transaction.settlement.resultItemType')"><el-select v-model="query.resultItemType" clearable filterable :placeholder="t('common.pleaseSelect')"><el-option v-for="item in itemTypes" :key="item" :label="itemTypeText(item)" :value="item" /></el-select></el-form-item>
            <el-form-item :label="t('transaction.settlement.resultRole')"><el-select v-model="query.resultRole" clearable :placeholder="t('common.pleaseSelect')"><el-option v-for="item in roles" :key="item" :label="roleText(item)" :value="item" /></el-select></el-form-item>
            <el-form-item :label="t('transaction.clearing.direction')"><el-select v-model="query.direction" clearable :placeholder="t('common.pleaseSelect')"><el-option :label="enumText('directionValue','CREDIT')" value="CREDIT" /><el-option :label="enumText('directionValue','DEBIT')" value="DEBIT" /></el-select></el-form-item>
            <el-form-item :label="t('transaction.settlement.targetCurrency')"><CurrencySelect v-model="query.targetCurrency" /></el-form-item>
            <el-form-item :label="t('transaction.settlement.businessDate')"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" :clearable="false" :range-separator="t('common.to')" :start-placeholder="t('common.startTime')" :end-placeholder="t('common.endTime')" /></el-form-item>
            <el-form-item><el-button type="primary" :icon="Search" @click="handleSearch">{{ t('common.search') }}</el-button><el-button :icon="RefreshLeft" @click="handleReset">{{ t('common.reset') }}</el-button></el-form-item>
        </el-form>
        <el-row :gutter="10" class="mb8"><el-col :span="1.5"><el-button v-hasPermi="'settlement:result-item:export'" type="warning" plain :icon="Download" :loading="exporting" @click="handleExport">{{ t('common.export') }}</el-button></el-col><el-col class="right-toolbar"><RightToolbar @toggle-search="showSearch=!showSearch" @refresh="loadData" /></el-col></el-row>
        <StandardTable v-loading="loading" table-key="admin-settlement-result-items" :data="rows" row-key="id" size="small">
            <el-table-column prop="settlementResultItemNo" :label="t('transaction.settlement.resultItemNo')" min-width="230" fixed="left" align="center" show-overflow-tooltip />
            <el-table-column prop="settlementBatchNo" :label="t('transaction.settlement.batchNo')" min-width="205" align="center"><template #default="{ row }"><el-button link type="primary" @click="openBatch(row.settlementBatchNo)">{{ row.settlementBatchNo }}</el-button></template></el-table-column>
            <el-table-column prop="merchantId" :label="t('transaction.fields.merchantId')" min-width="140" align="center"><template #default="{ row }"><el-button link type="primary" @click="openMerchant(row.merchantId)">{{ row.merchantId }}</el-button></template></el-table-column>
            <el-table-column prop="sourceTransactionId" :label="t('transaction.fields.transactionId')" min-width="205" align="center" show-overflow-tooltip><template #default="{row}"><el-button v-if="row.sourceTransactionId" link type="primary" @click="openTransaction(row)">{{row.sourceTransactionId}}</el-button><span v-else>-</span></template></el-table-column>
            <el-table-column :label="t('transaction.settlement.paymentTypeMethod')" min-width="190" align="center"><template #default="{row}"><PaymentMethodDisplay :payment-types="dimensionItems('paymentTypeValue',row.paymentType)" :payment-methods="dimensionItems('paymentMethodValue',row.paymentMethod)" /></template></el-table-column>
            <el-table-column :label="t('transaction.fields.transactionType')" min-width="128" align="center"><template #default="{row}">{{enumText('transactionTypeValue',row.transactionType)}}</template></el-table-column>
            <el-table-column :label="t('transaction.settlement.resultItemType')" min-width="164" align="center"><template #default="{row}">{{ itemTypeText(row.resultItemType) }}</template></el-table-column>
            <el-table-column :label="t('transaction.settlement.resultRole')" min-width="168" align="center"><template #default="{row}">{{ roleText(row.resultRole) }}</template></el-table-column>
            <el-table-column :label="t('transaction.clearing.feeCategory')" min-width="140" align="center"><template #default="{row}">{{enumText('feeCategoryValue',row.feeCategory)}}</template></el-table-column>
            <el-table-column :label="t('transaction.clearing.direction')" width="96" align="center"><template #default="{row}"><DirectionTag :direction="row.direction" :label="enumText('directionValue',row.direction)" /></template></el-table-column>
            <el-table-column :label="t('transaction.settlement.sourceAmount')" min-width="160" align="right"><template #default="{row}">{{ moneyTextByExponent(row.sourceAmount,row.sourceCurrency,row.sourceCurrencyExponent) }}</template></el-table-column>
            <el-table-column :label="t('transaction.settlement.directRate')" min-width="170" align="right"><template #default="{row}">{{ decimalText(row.directRate) }}</template></el-table-column>
            <el-table-column :label="t('transaction.settlement.targetAmount')" min-width="170" align="right"><template #default="{row}">{{ moneyTextByExponent(row.targetAmount,row.targetCurrency,row.targetCurrencyExponent) }}</template></el-table-column>
            <el-table-column :label="t('transaction.settlement.appliedLimit')" width="116" align="center"><template #default="{row}">{{enumText('appliedLimitValue',row.appliedLimit)}}</template></el-table-column>
            <el-table-column :label="t('transaction.fields.transactionDateTime')" min-width="174" align="center"><template #default="{row}"><BaseDateTime :value="row.sourceTransactionDateTime" /></template></el-table-column>
            <el-table-column :label="t('common.operation')" width="92" fixed="right" align="center"><template #default="{row}"><el-button link type="primary" :icon="View" @click="openDetail(row)">{{ t('common.detail') }}</el-button></template></el-table-column>
        </StandardTable>
        <div v-show="total>0" class="pagination-container"><el-pagination v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" :total="total" :page-sizes="[10,20,50,100]" layout="total, sizes, prev, pager, next, jumper" background @current-change="loadData" @size-change="handleSearch" /></div>
        <el-drawer v-model="detailVisible" :title="t('transaction.settlement.resultDetail')" size="min(780px, 96vw)" destroy-on-close>
            <template v-if="detail">
                <el-descriptions :column="2" border size="small">
                    <el-descriptions-item :label="t('transaction.settlement.resultItemNo')" :span="2">{{detail.settlementResultItemNo}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.batchNo')"><el-button link type="primary" @click="openBatch(detail.settlementBatchNo)">{{detail.settlementBatchNo}}</el-button></el-descriptions-item><el-descriptions-item :label="t('transaction.fields.merchantId')"><el-button link type="primary" @click="openMerchant(detail.merchantId)">{{detail.merchantId}}</el-button></el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.sourceDetailNo')">{{detail.sourceDetailNo||'-'}}</el-descriptions-item><el-descriptions-item :label="t('transaction.fields.transactionId')"><el-button v-if="detail.sourceTransactionId" link type="primary" @click="openTransaction(detail)">{{detail.sourceTransactionId}}</el-button><span v-else>-</span></el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.paymentTypeMethod')"><PaymentMethodDisplay :payment-types="dimensionItems('paymentTypeValue',detail.paymentType)" :payment-methods="dimensionItems('paymentMethodValue',detail.paymentMethod)" align="start" /></el-descriptions-item><el-descriptions-item :label="t('transaction.fields.transactionType')">{{enumText('transactionTypeValue',detail.transactionType)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.resultItemType')">{{itemTypeText(detail.resultItemType)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.resultRole')">{{roleText(detail.resultRole)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.clearing.feeCategory')">{{enumText('feeCategoryValue',detail.feeCategory)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.clearing.direction')"><DirectionTag :direction="detail.direction" :label="enumText('directionValue',detail.direction)" /></el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.sourceAmount')">{{moneyTextByExponent(detail.sourceAmount,detail.sourceCurrency,detail.sourceCurrencyExponent)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.targetAmount')">{{moneyTextByExponent(detail.targetAmount,detail.targetCurrency,detail.targetCurrencyExponent)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.directRate')">{{decimalText(detail.directRate)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.unroundedTargetAmount')">{{decimalText(detail.unroundedTargetAmount)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.minimumTargetAmount')">{{decimalText(detail.minimumTargetAmount)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.maximumTargetAmount')">{{decimalText(detail.maximumTargetAmount)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.roundingMode')">{{enumText('roundingModeValue',detail.roundingMode)}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.appliedLimit')">{{enumText('appliedLimitValue',detail.appliedLimit)}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.accountId')">{{detail.settlementAccountId}}</el-descriptions-item><el-descriptions-item :label="t('transaction.settlement.businessDate')">{{detail.businessDate}}</el-descriptions-item>
                    <el-descriptions-item :label="t('transaction.settlement.ledgerIdempotencyKey')" :span="2">{{detail.ledgerIdempotencyKey||'-'}}</el-descriptions-item>
                    <el-descriptions-item :label="t('common.createTime')" :span="2"><BaseDateTime :value="detail.createTime" /></el-descriptions-item>
                </el-descriptions>
                <h3 class="detail-section-title">{{t('transaction.clearing.formulaSnapshot')}}</h3><pre class="formula-snapshot">{{settlementFormulaText(detail.formulaSnapshot,translateSettlementFormula)}}</pre>
            </template>
        </el-drawer>
    </div>
</template>
<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { Download,RefreshLeft,Search,View } from '@element-plus/icons-vue';import { ElMessage } from 'element-plus';import { DirectionTag, PaymentMethodDisplay } from '@acquiring/shared';import { useI18n } from 'vue-i18n';import { useRoute,useRouter } from 'vue-router';
import { exportSettlementResultItems,searchSettlementResultItems,type SettlementResultItem,type SettlementResultItemQuery } from '@/api/settlement';import BaseDateTime from '@/components/BaseDateTime/index.vue';import RightToolbar from '@/components/RightToolbar/index.vue';import StandardTable from '@/components/StandardTable/StandardTable.vue';import CurrencySelect from '@/views/exchange/CurrencySelect.vue';import MerchantRemoteSelect from '@/views/transaction/components/MerchantRemoteSelect.vue';import { businessDateFromBusinessNo,decimalText,defaultDateRange,moneyTextByExponent,settlementFormulaText } from '@/views/settlement/shared';
const {t,te}=useI18n();const route=useRoute(),router=useRouter();const itemTypes=['PRINCIPAL','FEE_COMPONENT','FEE_GROUP_FINAL','RESERVE_HOLD','RESERVE_RETURN','RESERVE_RELEASE','ADJUSTMENT','REVERSAL','NET_SETTLEMENT'];const roles=['TRACE','FINANCIAL_COMPONENT','LEDGER_POSTING'];const showSearch=ref(true),loading=ref(false),exporting=ref(false),detailVisible=ref(false);const rows=ref<SettlementResultItem[]>([]),total=ref(0),detail=ref<SettlementResultItem|null>(null),dateRange=ref<[string,string]>(defaultDateRange());const query=reactive<SettlementResultItemQuery>({beginBusinessDate:'',endBusinessDate:'',pageNo:1,pageSize:10});onMounted(()=>{query.settlementBatchNo=routeText('settlementBatchNo');query.sourceTransactionId=routeText('sourceTransactionId');const linkedBusinessDate=businessDateFromBusinessNo(query.settlementBatchNo);if(linkedBusinessDate)dateRange.value=[linkedBusinessDate,linkedBusinessDate];loadData()});
function requestQuery():SettlementResultItemQuery{return{...query,sourceDetailType:'TRANSACTION_CLEARING',settlementBatchNo:query.settlementBatchNo||undefined,merchantId:query.merchantId||undefined,sourceTransactionId:query.sourceTransactionId||undefined,resultItemType:query.resultItemType||undefined,resultRole:query.resultRole||undefined,direction:query.direction||undefined,targetCurrency:query.targetCurrency||undefined,beginBusinessDate:dateRange.value[0],endBusinessDate:dateRange.value[1]}}function enumText(group:string,value?:string){if(!value)return'-';const key=`transaction.settlement.${group}.${value}`;return te(key)?t(key):value}
async function loadData(){loading.value=true;try{const result=await searchSettlementResultItems(requestQuery());rows.value=result.records||[];total.value=result.total||0}catch(error){ElMessage.error(error instanceof Error?error.message:t('common.loadFailed'))}finally{loading.value=false}}function handleSearch(){query.pageNo=1;loadData()}function handleReset(){Object.assign(query,{settlementBatchNo:undefined,merchantId:undefined,sourceTransactionId:undefined,resultItemType:undefined,resultRole:undefined,direction:undefined,targetCurrency:undefined,pageNo:1});dateRange.value=defaultDateRange();loadData()}async function handleExport(){exporting.value=true;try{await exportSettlementResultItems(requestQuery())}catch(error){ElMessage.error(error instanceof Error?error.message:t('common.exportFailed'))}finally{exporting.value=false}}function openDetail(row:SettlementResultItem){detail.value=row;detailVisible.value=true}function openTransaction(row:SettlementResultItem){router.push({path:'/transaction/operation',query:{transactionId:row.sourceTransactionId,transactionDateTime:row.sourceTransactionDateTime,transactionTimeZone:'Asia/Shanghai'}})}function openBatch(settlementBatchNo:string){router.push({path:'/settlement/batches',query:{settlementBatchNo}})}function openMerchant(merchantId:string){router.push({path:'/merchant/info',query:{merchantId}})}function routeText(key:string){const value=route.query[key];return typeof value==='string'&&value.trim()?value.trim():undefined}function itemTypeText(value?:string){return enumText('resultItemTypeValue',value)}function roleText(value?:string){return enumText('resultRoleValue',value)}function dimensionItems(group:string,value?:string){return value?[{value,label:enumText(group,value)}]:[]}function translateSettlementFormula(key:string){return t(key)}
</script>
<style scoped>.search-form :deep(.el-input),.search-form :deep(.el-select){width:220px}.detail-section-title{font-size:14px;margin:24px 0 10px;letter-spacing:0}.formula-snapshot{white-space:pre-wrap;overflow-wrap:anywhere;background:#f6f7f9;border:1px solid #e5e7eb;padding:14px;font-size:12px}</style>
